CREATE TABLE settings(key TEXT PRIMARY KEY,value_json TEXT);
CREATE TABLE payment_accounts(id INTEGER PRIMARY KEY,name TEXT,kind TEXT,is_active INTEGER,sort_order INTEGER);
CREATE TABLE bank_import_batches(id INTEGER PRIMARY KEY,payment_account_id INTEGER,created_at TEXT,imported_count INTEGER);
CREATE TABLE bank_transactions(id INTEGER PRIMARY KEY,payment_account_id INTEGER,booking_date TEXT,status TEXT);
CREATE TABLE members(id INTEGER PRIMARY KEY,name TEXT,contribution_interval TEXT,contribution_amount REAL,next_due_date TEXT,join_date TEXT,leave_date TEXT,status TEXT);
CREATE TABLE membership_payments(id INTEGER PRIMARY KEY,member_id INTEGER,period_key TEXT,date_paid TEXT);
CREATE TABLE invoices(id INTEGER PRIMARY KEY,party TEXT,due_date TEXT,voucher_type TEXT,gross_amount REAL);
CREATE TABLE invoice_payments(invoice_id INTEGER,amount REAL);
CREATE TABLE recurring_bookings(id INTEGER PRIMARY KEY,name TEXT,type TEXT,status TEXT,amount REAL,amount_mode TEXT,vat_rate REAL,variable_amount INTEGER,frequency TEXT,anchor_day INTEGER,next_due_date TEXT,end_date TEXT);
CREATE TABLE recurring_occurrences(recurring_booking_id INTEGER,scheduled_date TEXT,status TEXT);
CREATE TABLE reimbursements(id INTEGER PRIMARY KEY,title TEXT,due_date TEXT);
CREATE TABLE reimbursement_links(reimbursement_id INTEGER,role TEXT,amount_cents INTEGER);
CREATE TABLE member_advances(id INTEGER PRIMARY KEY,recipient_name TEXT,issued_at TEXT,amount REAL,resolved_at TEXT);
CREATE TABLE submissions(id INTEGER PRIMARY KEY,description TEXT,submitted_by TEXT,status TEXT);
CREATE TABLE ai_jobs(id INTEGER PRIMARY KEY,title TEXT,type TEXT,status TEXT);
CREATE TABLE budgets(id INTEGER PRIMARY KEY,name TEXT,start_date TEXT,end_date TEXT,amount_planned REAL,is_archived INTEGER);
CREATE TABLE earmarks(id INTEGER PRIMARY KEY,name TEXT,start_date TEXT,end_date TEXT,budget REAL,is_active INTEGER);
CREATE TABLE vouchers(id INTEGER PRIMARY KEY,type TEXT,date TEXT,sphere TEXT,gross_amount REAL,budget_id INTEGER,budget_amount REAL,earmark_id INTEGER,earmark_amount REAL);
CREATE TABLE voucher_budgets(voucher_id INTEGER,budget_id INTEGER,amount REAL);
CREATE TABLE voucher_earmarks(voucher_id INTEGER,earmark_id INTEGER,amount REAL);
